using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT environment variable is required.");
        var modelId = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL") ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(modelId)
            .AsIChatClient();
    }

    [AssemblyInitialize]
    public static void Initialize(TestContext _)
    {
        var chatClient = CreateChatClient();

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Path.GetTempPath(), "MyApp.Evaluation"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(chatClient));
    }

    [AssemblyCleanup]
    public static void Cleanup()
    {
        (s_reportingConfiguration as IDisposable)?.Dispose();
    }

    [TestMethod]
    public async Task Chat_RespondsCoherently()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_RespondsCoherently),
            iterationName: "default");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of using Azure OpenAI in a distributed application?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.ToChatMessage());

        await scenario.EvaluateAsync(messages);

        scenario.AssertMetricPassesThreshold(
            new CoherenceEvaluator().EvaluationMetricNames.First(), 3.0);
    }

    [TestMethod]
    public async Task Chat_AnswersRelevantly()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_AnswersRelevantly),
            iterationName: "default");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how to configure an Azure OpenAI resource in an Aspire application.")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.ToChatMessage());

        await scenario.EvaluateAsync(messages);

        scenario.AssertMetricPassesThreshold(
            new RelevanceEvaluator().EvaluationMetricNames.First(), 3.0);
    }

    [TestMethod]
    public async Task Chat_MultiTurnConversation_MaintainsContext()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_MultiTurnConversation_MaintainsContext),
            iterationName: "default");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to build a chatbot using Azure OpenAI.")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.ToChatMessage());

        messages.Add(new ChatMessage(ChatRole.User, "What model should I use for that?"));
        response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.ToChatMessage());

        await scenario.EvaluateAsync(messages);

        scenario.AssertMetricPassesThreshold(
            new CoherenceEvaluator().EvaluationMetricNames.First(), 3.0);
        scenario.AssertMetricPassesThreshold(
            new RelevanceEvaluator().EvaluationMetricNames.First(), 3.0);
    }

    [TestMethod]
    public async Task Chat_GroundedInContext_WithSystemPrompt()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_GroundedInContext_WithSystemPrompt),
            iterationName: "default");

        var context = "Azure OpenAI can be added to an Aspire app host using builder.AddAzureOpenAIChatClient(). " +
            "This registers an Azure OpenAI resource and configures a chat client deployment.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are an assistant that helps developers build distributed applications with .NET Aspire. Only answer questions related to .NET Aspire and Azure services."),
            new(ChatRole.User, "How do I add an Azure OpenAI resource to my Aspire app host?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.ToChatMessage());

        await scenario.EvaluateAsync(
            messages,
            additionalContext: [new GroundednessEvaluatorContext(context)]);

        scenario.AssertMetricPassesThreshold(
            new GroundednessEvaluator().EvaluationMetricNames.First(), 3.0);
        scenario.AssertMetricPassesThreshold(
            new FluencyEvaluator().EvaluationMetricNames.First(), 3.0);
    }
}

